+
+    expect(result.current.openGroupIds).toEqual(["group", "group.nested"]);
+    act(() => result.current.setOpenGroupIds([]));
+    unmount();
+    const next = renderHook(useGroups, { wrapper });
+
+    expect(next.result.current.openGroupIds).toEqual([]);
+  });
+});
