from airflow.sdk import dag, task, task_group


@task.short_circuit()
def no() -> bool:
    return False


@task.short_circuit()
def fifty_fifty() -> bool:
    return random() > 0.5


@task.python()
def printstr(value: str) -> None:
    print(value)


@task.python()
def get_rand_strs(s: int, k: int) -> List[str]:
    return ["".join(sample(ascii_letters, k)) for _ in range(s)]


@dag(
    "playground",
    description="Try random things",
    schedule=None,
    start_date=datetime(2024, 11, 1, 0, 0, 0, 0, ZoneInfo("Europe/Berlin")),
    catchup=False,
    dag_display_name="Playground",
)
def playground():
    @task_group()
    def group_1(somestr: str):
        (
            fifty_fifty()
            >> printstr(somestr)  # Should be skipped about half the time, but isn't
        )

    @task_group()
    def group_2(somestr: str):
        printstr(f"{somestr} again")  # Should also be skipped about half the time, isn't either

    strings = get_rand_strs(20, 10)
    group_1.expand(somestr=strings) >> group_2.expand(somestr=strings)
    no() >> printstr("Should be skipped and is.")


playground()
