#![no_main]

use std::sync::Arc;

use futures::StreamExt as _;
use libfuzzer_sys::arbitrary::Arbitrary;
use libfuzzer_sys::fuzz_target;
use vllm_llm::{GenerateOutput, GeneratePromptInfo};
use vllm_text::output::{TextDecodeOptions, decoded_text_event_stream};
use vllm_tokenizer::DynTokenizer;
use vllm_tokenizer::test_utils::TestTokenizer;

#[derive(Arbitrary, Debug)]
struct Input {
    skip_special_tokens: bool,
    include_stop_str_in_output: bool,
    intermediate: bool,
    min_tokens: u8,
    /// Mirrors the request's `stop` array.
    stop_strings: Vec<String>,
    prompt_token_ids: Vec<u16>,
    /// One entry per engine step; each carries that step's new token ids.
    steps: Vec<Vec<u16>>,
}

const MAX_STEPS: usize = 64;
const MAX_TOKENS_PER_STEP: usize = 64;
const MAX_STOPS: usize = 8;

/// Byte-fallback ids 0..=255 plus a few multi-byte and special tokens, so the
/// UTF-8 prefix-diffing logic in the decoder actually has work to do.
fn tokenizer() -> DynTokenizer {
    Arc::new(
        TestTokenizer::new()
            .with_regular_token("hello", 256)
            .with_regular_token("世界", 257)
            .with_regular_token("<think>", 258)
            .with_regular_token("</think>", 259)
            .with_special_token("<|eot|>", 260),
    )
}

fuzz_target!(|input: Input| {
    if input.steps.is_empty() || input.steps.len() > MAX_STEPS {
        return;
    }
    if input.steps.iter().any(|s| s.len() > MAX_TOKENS_PER_STEP) {
        return;
    }
    if input.stop_strings.len() > MAX_STOPS {
        return;
    }
    // Already reported (decoded.rs:130 underflow / :325 windows(0)), and the
    // REST routes reject it anyway. Skip it so the fuzzer explores past it.
    if input.stop_strings.iter().any(|s| s.is_empty()) {
        return;
    }
    if input.prompt_token_ids.len() > MAX_TOKENS_PER_STEP {
        return;
    }

    let prompt_token_ids: Arc<[u32]> =
        input.prompt_token_ids.iter().map(|&t| t as u32).collect();

    let last = input.steps.len() - 1;
    let outputs: Vec<vllm_llm::Result<GenerateOutput>> = input
        .steps
        .iter()
        .enumerate()
        .map(|(i, step)| {
            Ok(GenerateOutput {
                request_id: "fuzz".to_string(),
                // The decoder asserts the first output carries prompt metadata.
                prompt_info: (i == 0).then(|| GeneratePromptInfo {
                    prompt_token_ids: prompt_token_ids.clone(),
                    prompt_logprobs: None,
                }),
                token_ids: step.iter().map(|&t| t as u32).collect(),
                logprobs: None,
                finish_reason: (i == last).then_some(vllm_llm::FinishReason::Length),
                cached_token_count: 0,
                kv_transfer_params: None,
                ec_transfer_params: None,
            })
        })
        .collect();

    let decode_options = TextDecodeOptions {
        skip_special_tokens: input.skip_special_tokens,
        include_stop_str_in_output: input.include_stop_str_in_output,
        stop_strings: (!input.stop_strings.is_empty()).then(|| input.stop_strings.clone()),
        min_tokens: input.min_tokens as u32,
    };

    let stream = decoded_text_event_stream(
        "fuzz".to_string(),
        tokenizer(),
        futures::stream::iter(outputs),
        decode_options,
        input.intermediate,
    );

    // No IO in this pipeline, so a bare executor is enough.
    futures::executor::block_on(async {
        futures::pin_mut!(stream);
        while let Some(event) = stream.next().await {
            if event.is_err() {
                break;
            }
        }
    });
});

