# layers 0-2 carry a full DSA indexer k_cache next to the MLA cache.
# Full-model run (TP8 vs DEP8, two free nodes) is full-glm.yaml.
apiVersion: v1
kind: ConfigMap
metadata:
  name: xtp-entrypoint
  namespace: nilig-p2p
data:
  run.sh: |
    #!/bin/bash
    set -e
    find /dev/shm -type f -delete
    # Truncated-layer smoke only: the DSA loader indexes params_dict for every
    # checkpoint tensor, so drop tensors of layers beyond num_hidden_layers
    # before the loop. Full-model runs (NUM_LAYERS unset) skip this edit.
    if [ -n "${NUM_LAYERS}" ]; then python3 - <<'PY'
    p="/usr/local/lib/python3.12/dist-packages/vllm/models/deepseek_v32/nvidia/model.py"
    s=open(p).read()
    anchor="        loaded_params: set[str] = set()\n"
    ins=anchor+("        _nl = self.config.num_hidden_layers\n"
        "        weights = ((n, w) for n, w in weights if not ((m := __import__('re').match(r'^(model\\.)?layers\\.(\\d+)\\.', n)) and int(m.group(2)) >= _nl))\n")
    assert s.count(anchor)==1, s.count(anchor)
    s=s.replace(anchor,ins)
    open(p,"w").write(s); print("patched loader for truncated layers")
    PY
    fi
    CANON=${CANONICAL_LAYOUT:-true}
    KV_TRANSFER_CONFIG='{"kv_connector":"OffloadingConnector","kv_role":"kv_both",
